use std::{fs,io::{self,Write},path::{Path,PathBuf},time::{SystemTime,UNIX_EPOCH}};
pub fn root()->PathBuf{std::env::var_os("SPI3DER_STORE").map(PathBuf::from).unwrap_or_else(||std::env::var_os("HOME").map(PathBuf::from).unwrap_or_else(||PathBuf::from(".")).join(".spi3derr/store"))}
fn name(n:&str)->io::Result<&str>{if n.is_empty()||n=="."||n==".."||n.chars().any(|c|!(c.is_alphanumeric()||" -_.".contains(c))){Err(io::Error::new(io::ErrorKind::InvalidInput,"invalid store name"))}else{Ok(n)}}
pub fn path(n:&str)->io::Result<PathBuf>{Ok(root().join(format!("{}.3draft",name(n)?)))}
pub fn atomic(p:&Path,data:&str)->io::Result<()>{let dir=p.parent().filter(|x|!x.as_os_str().is_empty()).unwrap_or(Path::new("."));fs::create_dir_all(dir)?;let stamp=SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos();let tmp=dir.join(format!(".save-{}-{stamp}",std::process::id()));let result=(||{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&tmp)?;f.write_all(data.as_bytes())?;f.sync_all()?;fs::rename(&tmp,p)?;Ok(())})();if result.is_err(){let _=fs::remove_file(&tmp);}result}
pub fn list()->io::Result<Vec<String>>{let mut a=vec![];if !root().exists(){return Ok(a)}for e in fs::read_dir(root())?{let p=e?.path();if p.extension().and_then(|x|x.to_str())==Some("3draft"){a.push(p.file_stem().unwrap().to_string_lossy().into_owned());}}a.sort();Ok(a)}
